import{PostMessageApiServer}from"chrome://resources/ash/common/post_message_api/post_message_api_server.js";import{PromiseResolver}from"chrome://resources/ash/common/promise_resolver.js";export class ParentAccessController extends PostMessageApiServer{constructor(webviewElement,targetURL,originURLPrefix){super(webviewElement,targetURL,originURLPrefix);this.parentAccessCallbackReceivedResolver=new PromiseResolver;this.initializationErrorResolver=new PromiseResolver;this.registerMethod("onParentAccessResult",(param=>{this.parentAccessResult(param[0])}))}whenInitializationError(){return this.initializationErrorResolver.promise}onInitializationError(origin){this.initializationErrorResolver.reject(origin)}whenParentAccessCallbackReceived(){return this.parentAccessCallbackReceivedResolver.promise}parentAccessResult(parentAccessResultProto){this.parentAccessCallbackReceivedResolver.resolve(parentAccessResultProto);this.parentAccessCallbackReceivedResolver=new PromiseResolver}}